{
  "summary": "The function computes a CRC-32 checksum of the input data.",
  "proposed_name": "fn_01",
  "algorithm": "CRC-32",
  "self_confidence": 1.0,
  "claims": [
    {
      "id": "1",
      "type": "CONST",
      "text": "The function uses the CRC-32 polynomial 0xEDB88320.",
      "asserted_values": ["0xEDB88320"],
      "confidence": 1.0
    },
    {
      "id": "2",
      "type": "IO",
      "text": "Returns 0 when the input length is 0.",
      "asserted_values": [],
      "confidence": 1.0,
      "io": {
        "when": "param_2 == 0",
        "returns": "0"
      }
    },
    {
      "id": "3",
      "type": "IO",
      "text": "Returns VERA_ERR when the output capacity is smaller than the input length.",
      "asserted_values": [],
      "confidence": 1.0,
      "io": {
        "when": "out_cap < param_2",
        "returns": "VERA_ERR"
      }
    },
    {
      "id": "4",
      "type": "SIDE",
      "text": "Writes exactly param_2 bytes to out and never modifies in.",
      "asserted_values": [],
      "confidence": 1.0
    },
    {
      "id": "5",
      "type": "CF",
      "text": "The function uses a nested loop to compute the CRC-32 checksum.",
      "asserted_values": [],
      "confidence": 1.0
    }
  ],
  "recovered_c": "uint64_t fn_01(const uint8_t *in, size_t len, uint64_t arg, uint8_t *out, size_t out_cap) {\n  if (len == 0) {\n    return 0;\n  }\n  if (out_cap < len) {\n    return VERA_ERR;\n  }\n  uint32_t crc = 0xFFFFFFFF;\n  for (size_t i = 0; i < len; i++) {\n    crc ^= in[i];\n    for (int j = 0; j < 8; j++) {\n      crc = -(crc & 1) & 0xEDB88320 ^ crc >> 1;\n    }\n  }\n  return ~crc;\n}"
}
